./tg --help | head -40 && python3 -c "
import json;g=json.load(open('graph.json'));
print('rev',g.get('revision'))
for n in g['nodes']:
    if any(k in json.dumps(n).lower() for k in ['cpu','intention','notif','satisf','objective','concern']):
        print(n['id'],'|',n.get('type'),'|',n.get('status'),'|',(n.get('text') or n.get('title') or '')[:160])
"

